#!/bin/bash
# Stamp the app's Info.plist with the git commit and the build time, so an
# installed Quip can always say which code it is. Runs as a pre-build phase
# on every build (QuipMac/project.yml, QuipiOS/project.yml) and edits the
# SOURCE Info.plist in SRCROOT: both are generated by xcodegen and gitignored,
# so nothing tracked changes, and Xcode's own plist processing and code
# signing run after it (a post-build edit of the built plist broke the
# signature).
#
# Keys written (read by Shared/BuildInfo.swift):
#   QuipBuildCommit  short hash, "-dirty" when tracked files differ from HEAD
#                    (the regenerated project.pbxproj never counts, US-005)
#   QuipBuildDate    local build time, "YYYY-MM-DD HH:MM"
#   QuipBuildNumber  commit count at HEAD: the number that advances with
#                    every commit while the marketing version sits still.
#                    CFBundleVersion is left alone — the watch app and the
#                    extensions must match it, and they are not stamped.
#                    Absent when there is no history to count.
set -euo pipefail

plist="${SRCROOT:-}/${INFOPLIST_FILE:-}"
if [ ! -f "$plist" ]; then
  echo "stamp-build-info: no Info.plist at '$plist', nothing stamped" >&2
  exit 0
fi

repo="${SRCROOT:-$(pwd)}/.."
commit="unknown"
if git -C "$repo" rev-parse --short=7 HEAD >/dev/null 2>&1; then
  commit="$(git -C "$repo" rev-parse --short=7 HEAD)"
  # Generated project files and the tracked plugin database that tooling
  # rewrites on its own are not source changes.
  if [ -n "$(git -C "$repo" status --porcelain --untracked-files=no -- . ':(exclude)*.pbxproj' ':(exclude)*.db' 2>/dev/null)" ]; then
    commit="${commit}-dirty"
  fi
fi
number=""
if [ "$commit" != "unknown" ]; then
  number="$(git -C "$repo" rev-list --count HEAD 2>/dev/null || true)"
fi
date="$(date '+%Y-%m-%d %H:%M')"

pb=/usr/libexec/PlistBuddy
for key in QuipBuildCommit QuipBuildDate QuipBuildNumber; do
  "$pb" -c "Delete :$key" "$plist" >/dev/null 2>&1 || true
done
"$pb" -c "Add :QuipBuildCommit string $commit" "$plist"
"$pb" -c "Add :QuipBuildDate string $date" "$plist"
if [ -n "$number" ]; then
  "$pb" -c "Add :QuipBuildNumber string $number" "$plist"
fi
echo "stamp-build-info: $commit build=${number:-?} $date -> $plist"
